-- Avis d'initiative : contenu éditable de la page /avis-initiative.
-- Lecture publique. Écriture réservée au tableau de bord (rôle postgres) et à service_role.

CREATE TABLE public."Avis_initiative" (
	id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
	created_at timestamptz NOT NULL DEFAULT now(),
	ordre integer NOT NULL,
	type text NOT NULL,
	texte text NOT NULL,
	ancre text,
	CONSTRAINT avis_initiative_ordre_key UNIQUE (ordre),
	CONSTRAINT avis_initiative_type_check CHECK (
		type IN (
			'titre',
			'soustitre',
			'date',
			'description',
			'h2',
			'h3',
			'kicker',
			'p',
			'li',
			'note'
		)
	)
);

COMMENT ON TABLE public."Avis_initiative" IS
	'Contenu de la page Avis d''initiative, dans l''ordre d''affichage.';

ALTER TABLE public."Avis_initiative" ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Lecture publique Avis_initiative"
	ON public."Avis_initiative"
	FOR SELECT
	TO anon, authenticated
	USING (true);

REVOKE ALL ON TABLE public."Avis_initiative" FROM anon, authenticated, PUBLIC;
GRANT SELECT ON TABLE public."Avis_initiative" TO anon, authenticated;
GRANT ALL ON TABLE public."Avis_initiative" TO service_role;

REVOKE ALL ON SEQUENCE public."Avis_initiative_id_seq" FROM anon, authenticated, PUBLIC;
GRANT USAGE, SELECT ON SEQUENCE public."Avis_initiative_id_seq" TO service_role;

