INSERT INTO public."Avis_initiative" (ordre, type, texte, ancre)
VALUES
(1, 'titre', 'Première lecture de l’avant-projet de décret CISP', NULL),
(2, 'soustitre', 'Avis de l’Interfédé', NULL),
(3, 'date', '2026-10-07', NULL),
(4, 'description', 'Avis de l’Interfédé du 7 octobre 2026 sur l’avant-projet de décret CISP : accès des publics, évaluation, financement et représentation du secteur.', NULL),
(5, 'h2', 'SYNTHESE DES POINTS D’ATTENTION PRIORITAIRES', 'synthese-des-points-d-attention-prioritaires'),
(6, 'h3', '1. Accessibilité et autonomie du dispositif', '1-accessibilite-et-autonomie-du-dispositif'),
(7, 'li', 'Supprimer la disposition instaurant un seuil uniforme d’activité comme condition d’agrément et réaliser une <strong>analyse objectivée, par territoire, de la viabilité et de la pertinence de l’offre,</strong> tenant compte notamment des besoins des publics, de l’accessibilité de l’offre et des spécificités des filières.', NULL),
(8, 'li', 'Maintenir la possibilité pour les centres d’accueillir directement des stagiaires sans <strong>validation préalable par le FOREm et les CPAS des entrées spontanées.</strong>', NULL),
(9, 'li', 'Reconsidérer <strong>les définitions de l’employabilité</strong> et leurs modalités d’application pour déterminer l’accès aux opérateurs. Inclure <strong>l’employabilité moyenne</strong> dans le public éligible, notamment afin de préserver l’accès aux filières professionnalisantes, la liberté de choix du stagiaire et la nécessaire mixité des publics dans les formations CISP.', NULL),
(10, 'li', 'Consacrer le principe d’une <strong>relation partenariale réciproque / équilibrée entre le FOREm et les CISP, respectueuse de leur autonomie associative et pédagogique.</strong>', NULL),
(11, 'h3', '2. Évaluation du dispositif', '2-evaluation-du-dispositif'),
(12, 'li', 'Garantir que toute décision de retrait d’agrément d’une filière repose sur <strong>la seule appréciation globale, pluriannuelle et multicritère de l’action</strong> du centre et que les résultats de sortie positive ne puissent constituer un mécanisme autonome et annuel de retrait de filières.', NULL),
(13, 'li', 'Intégrer à l’évaluation multicritère des indicateurs permettant d’apprécier la <strong>progression des compétences</strong> ainsi que les <strong>impacts sociaux directs et indirects</strong> de la formation, afin de valoriser l’ensemble des effets du parcours et pas uniquement la situation du stagiaire à sa sortie.', NULL),
(14, 'li', 'Mettre sur pied d’égalité les différents types d’insertion et valoriser à <strong>1 l’entrée en formation professionnalisante</strong> et les <strong>sorties intermédiaires</strong>, en reconnaissant notamment les poursuites de parcours auprès d’autres opérateurs, dont les MIRE, sans les limiter aux seuls parcours multi-opérateurs reconnus par le FOREm.', NULL),
(15, 'li', 'Encadrer dans le décret <strong>la fixation des taux d’insertion attendus en tenant compte des réalités socioéconomiques territoriales, de la nature et des objectifs des filières et des caractéristiques des publics accueillis et de leur degré d’éloignement de l’emploi</strong>. La fixation ou la modification de ces taux doit en outre faire l’objet d’une concertation préalable avec les représentants du secteur et n’engendrer aucun effet rétroactif sur des années clôturées.', NULL),
(16, 'h3', '3. Financement et indexation du dispositif', '3-financement-et-indexation-du-dispositif'),
(17, 'li', '<strong>Supprimer le plafonnement du volume global d’heures agréées</strong> du secteur à 5,7 millions d’heures, afin de permettre l’adaptation de l’offre aux besoins des publics et des territoires. Revoir le <strong>mécanisme d’appels à candidatures de nouveaux opérateurs</strong> afin qu’il ne conduise pas à une remise en concurrence systématique de l’offre existante répondant aux besoins du marché. Si les contraintes budgétaires ne permettent temporairement aucune augmentation du volume global, un moratoire sur le développement de nouveaux centres apparaît préférable à un mécanisme conduisant à redistribuer tous les 3 ans une enveloppe fermée entre opérateurs.', NULL),
(18, 'li', 'Garantir une <strong>indexation annuelle automatique du taux horaire.</strong>', NULL),
(19, 'li', 'Garantir le <strong>transfert de la totalité des moyens APE</strong> dans l’enveloppe budgétaire des CISP et les pérenniser tant globalement qu’au niveau de chaque opérateur qui bénéficie actuellement d’une subvention APE.', NULL),
(20, 'h3', '4. Représentation du secteur', '4-representation-du-secteur'),
(21, 'li', 'Maintenir la continuité des <strong>missions collectives d’appui</strong> pédagogique et administratif, d’analyse sectorielle et statistique de l’offre de formation, et la formation des travailleurs du secteur.', NULL),
(22, 'li', 'Préserver une <strong>représentation unique et interfédérative</strong> forte et financée structurellement.', NULL),
(23, 'h2', 'OBJET DE L’AVIS', 'objet-de-l-avis'),
(24, 'p', 'A l’invitation du cabinet du ministre P-Y Jeholet, l’Interfédération des CISP (ci-après « l’Interfédé») émet un avis sur l’avant-projet de décret relatif aux Centres d’insertion socioprofessionnelle (CISP), présenté en première lecture au Gouvernement wallon le 17 septembre 2026.', NULL),
(25, 'p', 'Cet avant-projet s’inscrit dans le chantier de réformes du paysage de l’insertion socioprofessionnelle. Il réforme structurellement le dispositif CISP en redéfinissant notamment les conditions d’accès aux formations, les modalités d’agrément et de financement, les mécanismes d’évaluation et de programmation de l’offre, ainsi que les relations entre les CISP, le FOREm et les nouvelles instances de pilotage.', NULL),
(26, 'p', 'Compte tenu de l’ampleur des changements envisagés et de leurs conséquences directes sur les publics accompagnés, les travailleurs et les centres, l’Interfédé souhaite attirer l’attention du Gouvernement sur plusieurs dispositions de l’avant-projet et formuler des propositions de modification.', NULL),
(27, 'h2', 'PREAMBULE', 'preambule'),
(28, 'p', 'Cet avis est formulé par l’Organe d’administration de l’Interfédé, qui regroupe les cinq fédérations de l’insertion socioprofessionnelle en Wallonie : AID, ALEAP, CAIPS, Lire et Écrire Wallonie et UNESSA.', NULL),
(29, 'p', 'L’Interfédé partage la nécessité de faire évoluer le dispositif et de renforcer sa professionnalisation, la coopération entre acteurs, le suivi des parcours et l’évaluation. <strong>Ces évolutions doivent toutefois préserver les spécificités qui font la valeur ajoutée des CISP dans l’accompagnement des personnes les plus éloignées de l’emploi.</strong>', NULL),
(30, 'p', 'Plusieurs choix de la réforme soulèvent à cet égard des préoccupations : fragilisation de l’offre territoriale et de proximité, réduction de la souplesse des parcours et de l’autonomie des CISP, renforcement du rôle du FOREm et poids accru des résultats quantifiables dans l’évaluation.', NULL),
(31, 'p', '<strong>La réforme doit donc parvenir à professionnaliser sans uniformiser, optimiser sans éloigner l’offre des publics, mieux coordonner sans rigidifier les parcours et évaluer sans inciter à la sélection des personnes dont les résultats sont les plus facilement atteignables.</strong>', NULL),
(32, 'p', 'Dans cette perspective, les éléments déterminants du futur dispositif doivent être suffisamment balisés dans le décret, afin que l’accès aux formations, la programmation de l’offre, l’évaluation et l’autonomie des CISP ne dépendent pas principalement de décisions et de modalités d’application définies ultérieurement. La transformation demandée au secteur doit par ailleurs être accompagnée du temps, de l’accompagnement et des moyens nécessaires à sa réalisation.', NULL),
(33, 'p', 'C’est dans cette perspective que l’Interfédé concentre son avis sur quatre enjeux prioritaires : l’accès des publics et l’autonomie des CISP ; l’évaluation des centres et de leurs résultats ; le financement et les moyens de la professionnalisation ; la représentation et la coordination du secteur.', NULL),
(34, 'h2', '1. ACCESSIBILITE ET AUTONOMIE DU DISPOSITIF', '1-accessibilite-et-autonomie-du-dispositif-2'),
(35, 'h3', 'Instauration d’un seuil minimal à 40.000 heures', 'instauration-d-un-seuil-minimal-a-40-000-heures'),
(36, 'kicker', 'Article 9, §2', NULL),
(37, 'p', 'Le projet impose à chaque CISP un minimum de <strong>40.000 heures de formation agréées et subventionnées</strong>, indépendamment de sa situation, de son territoire ou du type de formations qu’il organise.', NULL),
(38, 'p', 'Selon l’analyse réalisée par notre secteur sur les volumes actuels, <strong>seuls 45 centres atteignent aujourd’hui ce seuil</strong>. Une part importante des CISP serait donc contrainte d’augmenter fortement son volume d’activités, de fusionner, de transférer ses activités ou de disparaître.', NULL),
(39, 'p', '<strong>L’Interfédé conteste le principe même d’un seuil minimal uniforme exprimé en nombre d’heures qui impose un principe de fusion aux asbl CISP, par essence autonomes dans leur choix, décisions et principes pédagogiques et de gestion.</strong>', NULL),
(40, 'p', 'Le volume d’activité d’un centre ne constitue, à lui seul, un indicateur ni de sa viabilité, ni de la qualité de son travail, ni de la pertinence de son offre en réponse aux besoins locaux. Il ne tient pas compte de la diversité des réalités des CISP : territoires couverts, publics accueillis, types de filières organisées, intensité de l’accompagnement ou spécificités pédagogiques.', NULL),
(41, 'p', 'Par ailleurs, certains centres sont multi-agréés et l’activité CISP n’est pas isolée d’autres actions. Cette réalité ne peut pas être ignorée. Elle représente environs deux tiers des centres.', NULL),
(42, 'p', 'Un tel seuil risque en particulier de <strong>fragiliser des offres pourtant nécessaires</strong> : petites structures spécialisées, opérateurs ruraux, offres de proximité ou filières répondant à des besoins spécifiques mais concernant un nombre plus limité de stagiaires. Pour des publics connaissant déjà d’importantes difficultés de mobilité, la concentration géographique de l’offre pourrait en outre renforcer les obstacles à l’accès et au maintien en formation. La disparition d’une offre de proximité peut également avoir des effets plus larges sur les personnes accompagnées, les CISP contribuant, par leur accompagnement global, à agir sur plusieurs déterminants sociaux de la santé tels que l’isolement, l’accès aux droits et aux soins, le logement, la mobilité, la formation ou l’emploi.', NULL),
(43, 'p', 'Les rapprochements, mutualisations ou collaborations entre centres peuvent constituer des réponses pertinentes lorsqu’ils répondent à une réalité ou à un besoin identifié. <strong>Ils ne peuvent cependant être imposés par l’application d’un seuil administratif uniforme</strong>, posé de manière arbitraire, sans démonstration que la taille d’un centre conditionne sa viabilité, le sens ou la qualité de l’offre proposée.', NULL),
(44, 'p', 'L’Interfédé demande dès lors <strong>la suppression du seuil minimal de 40.000 heures et, plus largement, du principe d’un seuil uniforme d’activité comme condition d’agrément</strong>.', NULL),
(45, 'h3', 'Publics éligibles et rôle du FOREm', 'publics-eligibles-et-role-du-forem'),
(46, 'kicker', 'Articles 5 et 6', NULL),
(47, 'p', 'La question de la <strong>redéfinition du public éligible</strong> pour les CISP est très problématique. L’article 5 réserve en principe l’accès aux CISP aux chercheurs d’emploi dont l’employabilité est calculée par le FOREm comme <strong>« faible » ou « très faible »</strong>. Or, la méthode de catégorisation présentée par le FOREm semble difficilement compatible avec cette restriction. L’arbre de décision prévoit qu’une personne présentant des obstacles multiples dépassant les seules dimensions professionnelles relève d’une employabilité très faible et que l’absence de projet professionnel ou une maîtrise insuffisante du français conduit à une employabilité faible. En revanche, dès lors que ces freins ne sont pas rencontrés, <strong>l’absence d’un positionnement métier considéré comme robuste ou d’une expérience professionnelle suffisante et récente conduit à classer le chercheur d’emploi en employabilité moyenne</strong>.', NULL),
(48, 'p', 'Il en résulte une <strong>incohérence majeure pour les filières professionnalisantes des CISP</strong>. Un chercheur d’emploi qui dispose d’un projet professionnel mais qui ne possède pas encore suffisamment les compétences nécessaires à l’exercice du métier visé relève précisément, selon cet arbre de décision, de l’employabilité moyenne. Si l’accès aux CISP est limité aux catégories faible et très faible, <strong>la personne sera donc inéligible au moment même où une formation professionnalisante en CISP pourrait constituer la réponse adaptée à ses besoins</strong>.', NULL),
(49, 'p', 'Le problème de l’arbre à décision réside aussi dans une vision linéaire des difficultés rencontrées par un chercheur d’emploi et leur résolution étape par étape, et non de façon intégrée et concomitante. Ainsi, un chercheur d’emploi ayant des freins “psychomédicosociaux” et un projet professionnel qualifié de non robuste doit pouvoir être envoyé vers une formation professionnalisante en CISP. Le risque est qu’il soit adressé vers une formation transversale puisque la première difficulté rencontrée relèvera de ce champ.', NULL),
(50, 'p', '<strong>La restriction de l’accès aux CISP sur la base du seul niveau d’employabilité pose problème.</strong> Elle va exclure des personnes pour lesquelles la pédagogie et l’accompagnement proposés par les CISP constituent pourtant la réponse adaptée et de fragiliser la nécessaire mixité des publics, notamment dans les EFT. Plus largement, l’Interfédé considère que la catégorie d’employabilité doit rester un outil d’aide à la décision et ne peut constituer, à elle seule, un critère déterminant d’accès aux opérateurs. <strong>Ces enjeux ont fait l’objet d’une interpellation commune des CISP et des MIRE en Commission régionale de concertation et sont développés dans une contribution conjointe adressée au Cabinet et au FOREm.</strong>', NULL),
(51, 'p', '<strong>La limitation du parcours à 3.600 heures de formation, tous CISP confondus, constitue une rigidité supplémentaire</strong>, peu compatible avec les besoins de certains publics qui nécessitent des parcours progressifs ou plusieurs étapes de formation. La possibilité d''un second droit de 3.600 heures étant soumise à une décision du FOREm, elle renforce également son pouvoir dans la détermination du parcours du stagiaire et nie l’expertise du CISP.', NULL),
(52, 'p', 'Plus largement, le projet renforce fortement le rôle du FOREm dans l’accès des publics aux CISP. Les centres doivent accueillir prioritairement les personnes que le FOREm ou le CPAS leur adresse. Que passe-t-il si le chercheur d’emploi adressé n’est pas accueilli en formation par le centre qui estime qu’il ne répond pas au cadre de celle-ci ? Sera-t-il pénalisé au final au moment de l’évaluation de sa collaboration avec le FOREm ?', NULL),
(53, 'p', 'Lorsqu’une personne se présente spontanément dans un CISP, <strong>son entrée en formation est par ailleurs soumise à une validation préalable du FOREm</strong> ou du CPAS dans un délai de cinq jours ouvrables (art. 6). <strong>L’Interfédé refuse cette logique de validation préalable, qu’elle relève du FOREm ou du CPAS.</strong> Elle remet en cause la capacité d’accueil direct des CISP et leur autonomie dans la décision d’admission, alors que les centres assurent eux-mêmes l’accueil, l’analyse de la demande, le diagnostic et, lorsque nécessaire, la réorientation des personnes.', NULL),
(54, 'h3', 'Relation partenariale avec le FOREm', 'relation-partenariale-avec-le-forem'),
(55, 'kicker', 'Articles 6, 9, 13, 20 et 21', NULL),
(56, 'p', 'Le FOREm intervient désormais non seulement dans l’orientation des publics et la validation des entrées, mais aussi dans la définition du contrat d’objectifs, la programmation de l’offre, le suivi des parcours et l’évaluation de la coopération avec les centres. La réforme fait ainsi évoluer la relation entre le FOREm et les CISP d’un partenariat vers une relation plus verticale, dans laquelle les CISP exécutent des orientations et objectifs définis en grande partie sans eux. C’est précisément le risque identifié dans les travaux préparatoires du secteur : une concentration de ces fonctions auprès d’un même acteur fragilise l’autonomie associative et pédagogique des centres.', NULL),
(57, 'p', 'Cette évolution est d’autant plus préoccupante que les CISP sont des <strong>opérateurs disposant d’une expérience et d’une expertise propre</strong>, notamment dans l’accueil des publics fragilisés et la construction de parcours adaptés. La réforme doit préserver une logique de <strong>confiance, de subsidiarité et de réciprocité entre partenaires</strong>, plutôt qu’instaurer une relation de prescripteur à prestataire.', NULL),
(58, 'p', '<strong>L’organisation des formations doit également préserver la capacité d’adaptation des CISP aux besoins des stagiaires.</strong> L’article 19 fixe une durée maximale de 1.500 heures pour les programmes des filières transversales et de 2.100 heures pour ceux des filières professionnalisantes, ainsi que des volumes minimaux respectifs de 8 et 30 heures de formation par semaine. <strong>L’Interfédé demande que la durée maximale des programmes soit portée à 2.100 heures pour l’ensemble des filières</strong>, certains apprentissages transversaux nécessitant également des parcours longs. Elle demande par ailleurs de <strong>confirmer explicitement que ces normes encadrent le programme de formation proposé par le centre et ne font pas obstacle à l’adaptation de la durée et du rythme du parcours individuel du stagiaire</strong>, notamment dans le cadre de son PIF et dans la limite des 3.600 heures.', NULL),
(59, 'p', 'La réforme renforce ainsi le rôle de coordination du FOREm et des CPAS dans les parcours. Cette coordination doit s’appuyer sur des <strong>mécanismes de concertation</strong> permettant aux opérateurs de contribuer à la mise en œuvre du dispositif et d’en ajuster les modalités lorsque des difficultés apparaissent.', NULL),
(60, 'h2', '2. EVALUATION DU DISPOSITIF', '2-evaluation-du-dispositif-2'),
(61, 'h3', 'Articles 9, 11, 13-16', 'articles-9-11-13-16'),
(62, 'p', 'L’avant-projet <strong>juxtapose plusieurs mécanismes d’évaluation</strong>, portant sur les centres, les filières, le contrat d’objectifs et les taux de sorties positives, sans que leur articulation apparaisse clairement.', NULL),
(63, 'p', 'Le projet prévoit une <strong>évaluation globale et triennale</strong> des centres. Elle porte notamment sur la qualité des actions, l’adéquation aux besoins territoriaux, l’assiduité, les sorties positives, les difficultés rencontrées et la collaboration avec le FOREm (art. 13).', NULL),
(64, 'p', '<strong>La prise en compte de l’assiduité dans cette évaluation appelle toutefois à la prudence.</strong> Les CISP accueillent précisément des publics dont les difficultés sociales, familiales, de santé ou de mobilité peuvent affecter la présence en formation. L’assiduité ne peut dès lors être considérée comme un indicateur de performance du centre sans tenir compte des caractéristiques des publics accueillis et des causes des absences.', NULL),
(65, 'p', 'À côté de cette évaluation globale, l’article 16 crée pourtant une seconde voie : <strong>le Gouvernement peut retirer directement l’agrément d’une filière si son taux de sortie positive (en n-1 et n-2) est inférieur au taux d’insertion fixé</strong>, indépendamment de l’évaluation globale prévue aux articles 13 et 14.', NULL),
(66, 'p', 'C’est particulièrement problématique puisque si le décret définit la valeur du taux de sortie positive, il ne fixe aucune balise substantielle quant à la détermination des taux minimaux à atteindre. Ceux-ci seront fixés ultérieurement par le Gouvernement, pour une période de trois ans. L’avenir d’une filière pourra donc dépendre d’un seuil dont le niveau et les critères de détermination ne sont pas suffisamment encadrés par le décret et, qui plus est, pourra varier tous les trois ans, avec un effet rétroactif.', NULL),
(67, 'p', 'Compte tenu des conséquences que ces taux peuvent avoir sur l’évaluation et l’agrément des filières, leur fixation ne peut relever de la seule appréciation du Gouvernement. Le décret doit en déterminer les principes et critères essentiels et imposer que les taux tiennent compte des réalités dans lesquelles les CISP exercent leurs missions. Un même niveau de résultat ne peut être attendu indépendamment de la situation socio-économique et du marché de l’emploi du territoire, du type et des objectifs de la filière ou encore des caractéristiques et du degré d’éloignement à l’emploi des publics accueillis.', NULL),
(68, 'p', 'Le mode lui-même de prise en compte d’une sortie positive doit être revu. L’article 11 valorise une mise à l’emploi à <strong>1</strong>, mais une entrée en formation professionnalisante ou une sortie intermédiaire<sup><a class="font-bold text-accent" href="#note-sortie-intermediaire">1</a></sup> à seulement <strong>0,75</strong>. Cette pondération est difficilement justifiable : pour les publics CISP, accéder à une formation qualifiante ou poursuivre son parcours peut précisément constituer l’aboutissement réussi du parcours d’insertion vers l’emploi.', NULL),
(69, 'p', 'Cette logique crée une incitation à sélectionner les stagiaires les plus susceptibles d’améliorer les indicateurs, alors que la mission des CISP consiste précisément à accompagner les personnes les plus éloignées de l’emploi. Par ailleurs, elle va limiter le recours à la sortie dite intermédiaire et annuler ainsi l’intérêt d’avoir introduit ce nouveau résultat ! En particulier, les partenariats avec les missions régionales risquent fort d’être restreints alors qu’ils ont une réelle valeur ajoutée.', NULL),
(70, 'p', 'Cette logique apparaît en outre <strong>en décalage avec les objectifs affichés dans l’exposé des motifs du projet</strong>. Celui-ci entend reconnaître <strong>« les compétences acquises par les stagiaires au sein des CISP »</strong>, mais aucun indicateur de résultat ne valorise réellement cette progression. Il affirme également vouloir préserver la <strong>vocation sociale des CISP</strong>, alors que celle-ci n’est pas intégrée dans les objectifs à atteindre et l’évaluation des résultats des centres.', NULL),
(71, 'p', 'Par ailleurs, <strong>l’évaluation devrait également mieux prendre en compte la progression réalisée par les stagiaires au cours de leur parcours.</strong> Pour les publics les plus éloignés de l’emploi, la réussite d’une formation ne se traduit pas toujours immédiatement par une mise à l’emploi ou une entrée en formation professionnalisante. <strong>L’acquisition et la progression de compétences, qu’elles soient transversales ou liées au métier, constituent en elles-mêmes un résultat essentiel du parcours.</strong>', NULL),
(72, 'note', 'Par « sortie intermédiaire », le décret entend une progression du stagiaire qui ne débouche pas encore directement sur un emploi ou une formation professionnalisante, mais qui se traduit soit par l’entrée dans un parcours combinant plusieurs opérateurs, soit par une amélioration de son niveau d’employabilité.', 'note-sortie-intermediaire'),
(73, 'p', 'Cette progression peut être objectivée à partir de référentiels de compétences existants et d’outils d’évaluation déjà mobilisés dans le secteur.', NULL),
(74, 'p', '<strong>L’évaluation devrait ainsi intégrer, au-delà des sorties positives, la progression des compétences ainsi que les impacts sociaux directs et indirects de l’accompagnement, notamment en matière de mobilité, de logement, d’accès aux droits et aux soins, d’autonomie ou encore de lien social. Ces dimensions permettent de rendre compte plus largement des effets du parcours et de la valeur ajoutée des CISP pour des publics particulièrement éloignés de l’emploi.</strong>', NULL),
(75, 'p', 'Enfin, le taux d’insertion ou de sortie positive devra s’apprécier au regard des stagiaires qui ont terminé leur formation.', NULL),
(76, 'h2', '3. FINANCEMENT ET INDEXATION DU DISPOSITIF', '3-financement-et-indexation-du-dispositif-2'),
(77, 'h3', 'Article 22 et 50 à 53', 'article-22-et-50-a-53'),
(78, 'p', 'La réforme modifie profondément les exigences imposées aux CISP : contrats d’objectifs triennaux, nouvelles obligations de suivi et d’encodage, alimentation du dossier unique, évaluation renforcée, adaptation aux nouvelles modalités de programmation de l’offre, etc. <strong>Ces nouvelles obligations nécessitent des moyens humains et organisationnels supplémentaires.</strong>', NULL),
(79, 'p', 'Dans le même temps, le projet de décret <strong>ne garantit plus l’indexation annuelle du taux horaire</strong>. L’article 22 prévoit uniquement que le Gouvernement <strong>« peut » indexer</strong> le taux horaire en janvier de chaque année. L’indexation devient donc une faculté dépendant des arbitrages budgétaires annuels, et non un mécanisme automatique permettant au financement de suivre l’évolution des coûts.', NULL),
(80, 'p', 'Cette disposition est particulièrement problématique dans un secteur dont les dépenses sont largement constituées de <strong>charges salariales</strong>, qui évoluent indépendamment des décisions budgétaires prises pour le dispositif CISP.', NULL),
(81, 'p', '<strong>Les centres subissent déjà depuis plusieurs années les effets de l’absence d’indexation de leur subvention. Jusqu’à présent, ils ont largement absorbé cette hausse des coûts afin de maintenir leur offre de formation, mais au prix d’une pression croissante sur leurs ressources humaines et leurs marges de fonctionnement. Les remontées du secteur font notamment état de non-remplacements de travailleurs, de réductions d’emploi, de reports d’investissements ou de réductions de certaines activités.</strong> La poursuite de cette situation ne peut constituer un mode durable de financement du dispositif.', NULL),
(82, 'p', 'Cette insécurité est d’autant plus difficilement compatible avec la réforme que celle-ci exige des centres <strong>la réalisation d’une offre stable</strong> : pour bénéficier pleinement de leur subvention, ils doivent réaliser 100% du volume d’heures pour lequel ils sont financés. Or, sans indexation garantie, leurs moyens peuvent progressivement décrocher de l’évolution réelle de leurs coûts. Il est difficile d’exiger des opérateurs qu’ils réalisent leur offre à 100 % sans leur garantir parallèlement les moyens nécessaires pour la mettre en œuvre.', NULL),
(83, 'p', '<strong>Le plafonnement du volume global d’heures agréées du secteur à 5,7 millions d’heures pose également question.</strong> Il fige l’offre de formation indépendamment de l’évolution des besoins des publics, des territoires et du marché de l’emploi. Combiné à une programmation de l’offre et à des appels à candidatures périodiques, ce mécanisme risque d’organiser une mise en concurrence des opérateurs au sein d’une enveloppe fermée, toute création ou augmentation d’une offre devant alors potentiellement s’opérer au détriment d’une autre.', NULL),
(84, 'p', 'L’Interfédé demande dès lors de <strong>supprimer le plafonnement du volume global d’heures agréées du secteur et de permettre une évolution de l’offre fondée sur une analyse objectivée des besoins</strong>.', NULL),
(85, 'p', 'Par ailleurs, les subventions APE sont progressivement retirées aux centres pour être réinjectées théoriquement au sein du secteur dans son ensemble. Toutefois, l’article 53 prévoit que les moyens ainsi libérés « <strong><em>peuvent être transférés</em></strong> » vers l’enveloppe budgétaire CISP.', NULL),
(86, 'p', '<strong>L’Interfédé demande que l’intégralité de ces moyens soit maintenue dans le secteur et que leur affectation soit clairement garantie.</strong>', NULL),
(87, 'p', 'Une clarification est également nécessaire concernant les montants APE identifiés dans l’annexe de l’avant-projet. Certains ne sont pas directement liés aux actions financées dans le cadre de l’agrément CISP, mais soutiennent d’autres missions ou dispositifs, notamment Digistart, la formation continue des travailleurs ou des actions développées dans le cadre d’appels à projets. Ces moyens doivent être identifiés distinctement et leur maintien garanti pour les missions auxquelles ils sont affectés.', NULL),
(88, 'p', 'L’Interfédé a transmis au Cabinet une proposition relative au transfert des moyens APE CISP, Digistart et Interfédé. <strong>Elle demande que les moyens APE directement liés à l’activité CISP puissent être convertis en heures agréées et que les modalités de reprise des autres moyens fassent l’objet d’une concertation avec le secteur.</strong>', NULL),
(89, 'h2', '4. REPRESENTATION ET COORDINATION DU SECTEUR', '4-representation-et-coordination-du-secteur'),
(90, 'h3', 'Article 25', 'article-25'),
(91, 'p', 'Le projet modifie profondément le modèle actuel de représentation du secteur en permettant au Gouvernement de reconnaître <strong>jusqu’à cinq organismes représentatifs</strong>, représentant chacun au minimum 300.000 heures de formation. Une démarche inverse à la tendance actuelle demandée par le Gouvernement dans d’autres secteurs d’une seule représentation (notamment celui de l’économie sociale).', NULL),
(92, 'p', 'Cette organisation va <strong>fragmenter la représentation</strong> alors que l’Interfédé constitue aujourd’hui l''espace commun voulu par les fédérations et leurs membres pour coordonner le secteur, élaborer des positions collectives et dialoguer avec les pouvoirs publics et les représentants politiques. La multiplication des interlocuteurs risque d’affaiblir la capacité d’une représentation cohérente du secteur et va à l’encontre de l’efficacité tant recherchée et à contrecourant de ce qui est impulsé dans les autres secteurs.', NULL),
(93, 'p', 'Le projet ne reprend par ailleurs plus explicitement plusieurs missions collectives <strong>actuellement exercées au niveau sectoriel</strong>, notamment l’appui administratif et pédagogique aux centres, l’analyse sectorielle et statistique de l’offre et des publics ou la formation des travailleurs.', NULL),
(94, 'p', 'Enfin, le financement de la représentation est fragilisé : l’article 25 prévoit que le Gouvernement <strong>« peut » octroyer une subvention</strong> aux organismes reconnus, là où le dispositif actuel garantit le financement de la coordination et de la représentation sectorielles à l’organisme désigné. Dans un contexte de réforme profonde, il est essentiel de préserver ces capacités collectives d’accompagnement et de coordination.', NULL),
(95, 'h2', 'CONSIDERATIONS FINALES', 'considerations-finales'),
(96, 'p', 'Les modifications proposées par l’Interfédé visent à permettre l’évolution et la professionnalisation du dispositif tout en préservant les conditions indispensables à l’accompagnement des personnes plus éloignées de l’emploi : accessibilité de l’offre, autonomie des CISP, souplesse des parcours et prise en compte de la diversité des publics et des territoires.', NULL),
(97, 'p', 'Cette vigilance est d’autant plus nécessaire que certaines conséquences de la réforme pourraient être difficilement réversibles : suppression d’une filière, abandon d’une implantation, dispersion d’une équipe, perte d’expertise ou rupture de partenariats. Il est donc indispensable de prévoir dans le dispositif des mécanismes de suivi, d’évaluation et d’ajustement permettant d’identifier rapidement les éventuels effets indésirables de la réforme et de les corriger avant qu’ils ne deviennent irréversibles.', NULL),
(98, 'p', '<strong>L’Interfédé demande dès lors que les modifications formulées dans le présent avis soient prises en compte avant l’adoption du texte en deuxième lecture, afin de sécuriser la mise en œuvre de la réforme et de préserver la capacité du secteur CISP à remplir pleinement ses missions.</strong>', NULL);
